function companyLogo(c,extra=''){const index=companies.findIndex(x=>x.id===c.id);return '<span class="company-logo '+extra+'" role="img" aria-label="'+esc(c.name)+' — დემო ლოგო"><img src="/assets/company-logomarks.png" class="logo-sheet" style="--logo-x:'+(-100*(index%4))+'%;--logo-y:'+(-100*Math.floor(index/4))+'%" alt=""><span class="logo-fallback" aria-hidden="true">'+icon('building-2')+'</span></span>';}
function profileHref(c){const base="/companies/"+c.slug+"/";return location.pathname==="/categories/"?base+"?from="+encodeURIComponent("/categories/"+location.search):base;}
function card(c){const photo=photos[c.id];const category=categories.find(x=>x.id===c.type);return `<article class="company-card"><a class="company-photo-wrap" href="${esc(profileHref(c))}" aria-label="${c.name} — პროფილის ნახვა"><img class="company-photo" src="/assets/photos/${photo[0]}" alt="${photo[1]} — საილუსტრაციო ფოტო" width="800" height="533" loading="lazy" decoding="async"><span class="photo-category">${category.title}</span></a><div class="company-body"><div class="company-top">${companyLogo(c)}<div><h3><a href="${esc(profileHref(c))}">${c.name}</a></h3><p class="company-location">${icon('map-pin')} ${c.cityLabel}, საქართველო</p></div></div><p class="company-description">${c.description}</p><div class="card-service-area">${icon('globe')} <span>${c.area}</span></div><div class="tags">${c.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div><div class="company-bottom"><a class="details-button" href="${esc(profileHref(c))}">გაიცანი კომპანია ${icon('arrow-up-right')}</a><span class="availability">${c.offer.length} შეთავაზება · დემო</span></div></div></article>`}
const grid=document.querySelector('#category-grid');if(grid)grid.innerHTML=categories.map((c,index)=>`<a class="category-card" href="/categories/?type=${c.id}"><span class="category-icon" aria-hidden="true"><img class="category-3d-sheet" src="/assets/category-business-3d.png" alt="" style="--category-x:${-100*(index%2)}%;--category-y:${-100*Math.floor(index/2)}%" decoding="async">${icon(categoryIcons[c.id])}</span><div><h3>${c.title}</h3><p>${c.sub}</p></div>${icon('arrow-up-right','category-arrow')}</a>`).join('');
const featured=document.querySelector('#featured-companies');if(featured)featured.innerHTML=companies.slice(0,3).map(card).join('');
document.querySelector('.nav-home')?.classList.add('active');
document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close)close.closest('dialog').close();});
const cityNames={tbilisi:'თბილისი',batumi:'ბათუმი',kutaisi:'ქუთაისი'};
const filterValues={type:Object.fromEntries(categories.map(c=>[c.id,c.title])),city:cityNames,language:{ka:'ქართული',en:'ინგლისური'},...filterOptions,sort:{relevance:'შესაბამისობის მიხედვით',name:'სახელის მიხედვით'}};
const defaultFilters={q:'',type:'',city:'',language:'',industry:'',collaboration:'',format:'',sort:'relevance'};
function validateFilters(input){if(!input||typeof input!=='object'||Array.isArray(input))throw Error('Invalid filters');if(Object.keys(input).some(k=>!(k in defaultFilters)))throw Error('Unknown filter');for(const [k,v] of Object.entries(input)){if(typeof v!=='string')throw Error('Filter values must be strings');if(k==='q'){if(v.length>200)throw Error('Query is too long');}else if(v&&!Object.hasOwn(filterValues[k],v))throw Error('Invalid '+k);}return {...defaultFilters,...input};}
function readFilters(search=location.search){const p=new URLSearchParams(search);const data={};for(const k of Object.keys(defaultFilters)){const value=p.get(k);if(!value)continue;try{validateFilters({[k]:value});data[k]=value;}catch{}}return validateFilters(data);}
function filterQuery(f){const p=new URLSearchParams();for(const [k,v] of Object.entries(f))if(v&&!(k==='sort'&&v==='relevance'))p.set(k,v);return p.toString();}
function safeCatalogFrom(raw){try{if(!raw)return '/categories/';const u=new URL(raw,location.origin);if(u.origin!==location.origin||!['/categories','/categories/'].includes(u.pathname))return '/categories/';const q=filterQuery(readFilters(u.search));return '/categories/'+(q?'?'+q:'');}catch{return '/categories/';}}
let filters=readFilters();
const stopWords=['ვეძებ','მინდა','მჭირდება','და','ან','საჭიროა','ბიზნესისთვის','სანდო'];
function searchTerms(q){return q.toLocaleLowerCase().split(/[\s,.;!?]+/).filter(x=>x&&!stopWords.includes(x)).map(x=>x.replace(/(ისთვის|ებში|ების|ებს|ის|ს)$/u,''));}
function getResults(f){const terms=searchTerms(f.q);const matches=companies.filter(c=>{if(f.type&&c.type!==f.type)return false;if(f.city&&!c.area.includes(cityNames[f.city])&&!c.area.includes('მთელი საქართველო'))return false;if(f.language==='en'&&!c.languages.includes('ინგლისური'))return false;if(f.industry&&c.industry!==f.industry)return false;if(f.collaboration&&!c.collaboration.includes(f.collaboration))return false;if(f.format&&!c.format.includes(f.format))return false;const words=(c.name+' '+c.description+' '+c.words+' '+c.offer.join(' ')+' '+filterOptions.industry[c.industry]).toLocaleLowerCase().split(/\s+/);return !terms.length||terms.every(t=>words.some(w=>w.includes(t)));});if(f.sort==='name')matches.sort((a,b)=>a.name.localeCompare(b.name));else if(terms.length){const score=c=>terms.reduce((sum,t)=>sum+(c.name.toLowerCase().includes(t)?3:0)+(c.tags.some(tag=>tag.includes(t))?2:0),0);matches.sort((a,b)=>score(b)-score(a));}return matches;}
function setFilters(next,{push=true}={}){filters=validateFilters({...filters,...next});const url=new URL(location.href);url.search=filterQuery(filters);if(push)history.pushState({},'',url);else history.replaceState({},'',url);renderResults();return getResults(filters);}
function facetCount(key,value){return getResults({...filters,[key]:value}).length;}
function renderResults(){const grid=document.querySelector('#results-grid');if(!grid)return;
 document.querySelector('#type-options').innerHTML=[{id:'',title:'ყველა კატეგორია'},...categories].map(c=>`<label class="radio-option"><input type="radio" name="type" value="${c.id}" ${filters.type===c.id?'checked':''}><span>${c.title}</span><small>${facetCount('type',c.id)}</small></label>`).join('');
 for(const key of ['city','language','industry','collaboration','format']){const el=document.querySelector('#'+key+'-filter');const any={city:'ყველა ქალაქი',language:'ყველა ენა',industry:'ყველა მიმართულება',collaboration:'ნებისმიერი ტიპი',format:'ნებისმიერი ფორმატი'}[key];el.innerHTML=`<option value="">${any}</option>`+Object.entries(filterValues[key]).map(([v,label])=>`<option value="${v}">${label} (${facetCount(key,v)})</option>`).join('');el.value=filters[key];}
 document.querySelector('#sort-filter').value=filters.sort;document.querySelector('#catalog-query').value=filters.q;
 const category=categories.find(c=>c.id===filters.type);document.querySelector('#catalog-title').textContent=category?category.title:'იპოვე შენი პარტნიორი';document.title=(category?category.title:'კატეგორიები და კომპანიები')+' — MeetAny';const results=getResults(filters);document.querySelector('#result-count').innerHTML=`<strong>${results.length} კომპანია</strong> <span>· ${results.reduce((sum,c)=>sum+c.offer.length,0)} შეთავაზება</span>`;
 const chips=Object.entries(filters).filter(([k,v])=>v&&k!=='sort').map(([k,v])=>[k,k==='q'?v:filterValues[k][v]]);document.querySelector('#active-filters').innerHTML=chips.map(([k,v])=>`<button class="filter-chip" data-remove-filter="${k}" aria-label="ფილტრის წაშლა: ${esc(v)}">${esc(v)} ${icon('x')}</button>`).join('');
 document.querySelector('#filter-toggle').innerHTML=icon('sliders-horizontal')+' ფილტრები'+(chips.length?' ('+chips.length+')':'');
 grid.innerHTML=results.length?results.map(card).join(''):`<div class="empty-state">${icon('search')}<h2>ამ პირობებით კომპანია ვერ მოიძებნა</h2><p>მოხსენი ერთ-ერთი არჩეული ფილტრი, შეცვალე საძიებო სიტყვა ან შექმენი შენი მოთხოვნა.</p><div class="form-actions"><button class="button button-outline" data-reset>ყველა ფილტრის გასუფთავება</button><button class="button" data-action="request">მოამზადე მოთხოვნა</button></div></div>`;
}
if(document.querySelector('#results-grid')){document.querySelector('.nav-home').classList.remove('active');document.querySelector('.nav-categories').classList.add('active');document.querySelector('#filters').addEventListener('change',e=>{const key=e.target.name==='type'?'type':e.target.id.replace('-filter','');if(Object.hasOwn(defaultFilters,key))setFilters({[key]:e.target.value});});document.querySelector('#sort-filter').addEventListener('change',e=>setFilters({sort:e.target.value}));document.querySelector('#catalog-search').addEventListener('submit',e=>{e.preventDefault();setFilters({q:document.querySelector('#catalog-query').value.trim()})});document.querySelector('#filter-toggle').addEventListener('click',e=>{const open=document.querySelector('#filters').classList.toggle('is-open');e.currentTarget.setAttribute('aria-expanded',String(open));if(open)document.querySelector('#filters').scrollIntoView({block:'start',behavior:'smooth'});});window.addEventListener('popstate',()=>{filters=readFilters();renderResults()});renderResults();}
let requestDraft={};let lastDraft=null;
function readValidDraft(form){
 const data={};
 for(const field of form.querySelectorAll('[name]')){
  const value=field.value.trim();
  field.setCustomValidity(field.required&&value.length<Math.max(1,field.minLength||0)?'შეავსე ველი სრულად; მხოლოდ გამოტოვებები საკმარისი არ არის.':'');
  data[field.name]=value;
 }
 return form.reportValidity()?data:null;
}
document.addEventListener('input',e=>{if(e.target.matches('#intro-form [name],#company-form [name]'))e.target.setCustomValidity('');});
function openRequest(companyId,offerIndex){const company=companies.find(c=>c.id===companyId);const selectedOffer=Number.isInteger(offerIndex)&&company?.offer[offerIndex]?company.offer[offerIndex]:'';const draftKey=(companyId||'general')+':'+(selectedOffer?offerIndex:'general');const draft=requestDraft[draftKey]||{};document.querySelector('#form-content').innerHTML=`<span class="section-kicker">${company?'საქმიანი გაცნობა':'ბიზნესმოთხოვნა'}</span><h2 id="form-title">${company?company.name+' — გაცნობა':'რას ეძებს შენი ბიზნესი?'}</h2><p>მოკლედ აღწერე შენი მიზანი და თანამშრომლობის პირობები.</p>${selectedOffer?`<p class="selected-offer">შეთავაზება: ${esc(selectedOffer)}</p>`:''}<form id="intro-form"><fieldset class="form-section"><legend><span>01</span> შენი საჭიროება</legend><div class="field"><label for="request-text">რა გჭირდება? *</label><textarea id="request-text" name="need" required minlength="10" maxlength="2000" placeholder="მაგალითად: ვეძებ სასტუმროსთვის თეთრეულის მომწოდებელს თბილისში.">${esc(draft.need||(selectedOffer?'დაინტერესებული ვარ: '+selectedOffer+'\n\n':'')||filters.q||'')}</textarea></div><div class="field"><label for="request-city">მომსახურების ადგილი *</label><input id="request-city" name="city" required maxlength="100" value="${esc(draft.city||cityNames[filters.city]||'')}" placeholder="მაგალითად: თბილისი"></div></fieldset><fieldset class="form-section"><legend><span>02</span> საკონტაქტო ინფორმაცია</legend><div class="field"><label for="request-name">შენი სახელი / კომპანია *</label><input id="request-name" name="name" required maxlength="120" value="${esc(draft.name||'')}" autocomplete="organization" placeholder="სახელი ან კომპანიის დასახელება"></div><div class="field"><label for="request-email">ელფოსტა *</label><input id="request-email" type="email" name="email" required maxlength="200" value="${esc(draft.email||'')}" autocomplete="email" placeholder="name@company.ge"></div></fieldset><p class="form-note form-status">საცდელი რეჟიმი: მოთხოვნა არ იგზავნება და სერვერზე არ ინახება. შეგიძლია მოამზადო და ჩამოტვირთო მისი ტექსტი.</p><button class="button form-submit" type="submit">მოთხოვნის მომზადება ${icon('arrow-right')}</button></form>`;const form=document.querySelector('#intro-form');form.addEventListener('input',()=>{requestDraft[draftKey]=Object.fromEntries(new FormData(form));});form.addEventListener('submit',e=>{e.preventDefault();const data=readValidDraft(form);if(!data)return;lastDraft={...data,company:company?.name||'პარტნიორი შესარჩევია'};document.querySelector('#form-content').innerHTML=`<div class="success-icon">${icon('check')}</div><h2 id="form-title">მოთხოვნა მომზადებულია</h2><div class="draft-summary"><span class="section-kicker">მოთხოვნის მიმღები</span><h3>${esc(lastDraft.company)}</h3><p style="white-space:pre-wrap">${esc(data.need)}</p><dl><div><dt>ადგილი</dt><dd>${esc(data.city)}</dd></div><div><dt>გამომგზავნი</dt><dd>${esc(data.name)}</dd></div><div><dt>ელფოსტა</dt><dd>${esc(data.email)}</dd></div></dl></div><p class="form-note">ეს მოთხოვნის მონახაზია — კომპანიასთან არ გაგზავნილა. ჩამოტვირთე ტექსტი შენს მოწყობილობაზე.</p><div class="form-actions"><button class="button" data-action="download">ტექსტის ჩამოტვირთვა ${icon('download')}</button><button class="button button-outline" data-close>დასრულება</button></div>`;});form.querySelector('textarea').addEventListener('input',e=>e.target.setCustomValidity(''));document.querySelector('#form-dialog').showModal();}
function openCompanyForm(){document.querySelector('#form-content').innerHTML=`<span class="section-kicker">შენი კომპანია MeetAny-ზე</span><h2 id="form-title">კომპანიის დამატება</h2><p>მოამზადე შენი კომპანიის პროფილის მოკლე ვერსია.</p><form id="company-form"><fieldset class="form-section"><legend><span>01</span> კომპანიის შესახებ</legend><div class="field"><label for="company-name">კომპანიის დასახელება *</label><input id="company-name" name="name" required maxlength="80"></div><div class="field"><label for="company-offer">რას სთავაზობ ბიზნესებს? *</label><textarea id="company-offer" name="offer" required minlength="10" maxlength="1500"></textarea></div></fieldset><fieldset class="form-section"><legend><span>02</span> მომსახურების არეალი</legend><div class="field"><label for="company-area">მომსახურების ტერიტორია *</label><input id="company-area" name="area" required maxlength="100" placeholder="მაგალითად: მთელი საქართველო"></div></fieldset><p class="form-note form-status">საცდელი რეჟიმი: პროფილი საჯაროდ არ გამოქვეყნდება. შეგიძლია ნახო და ჩამოტვირთო მისი ტექსტი.</p><button class="button form-submit" type="submit">პროფილის წინასწარი ნახვა ${icon('arrow-right')}</button></form>`;document.querySelector('#company-form').addEventListener('submit',e=>{e.preventDefault();const data=readValidDraft(e.target);if(!data)return;lastDraft={profile:true,...data};document.querySelector('#form-content').innerHTML=`<span class="section-kicker">პროფილის მონახაზი</span><h2 id="form-title">${esc(data.name)}</h2><p style="white-space:pre-wrap">${esc(data.offer)}</p><div class="detail-meta"><div><small>მომსახურების ტერიტორია</small>${esc(data.area)}</div></div><p class="form-note">პროფილი არ გამოქვეყნებულა. ეს ტექსტის წინასწარი ვერსიაა.</p><button class="button form-submit" data-action="download">პროფილის ტექსტის ჩამოტვირთვა ${icon('download')}</button>`;});document.querySelector('#form-dialog').showModal();}
document.addEventListener('click',e=>{if(e.target.closest('[data-reset]'))setFilters({...defaultFilters});const remove=e.target.closest('[data-remove-filter]');if(remove)setFilters({[remove.dataset.removeFilter]:''});const intro=e.target.closest('[data-intro]');if(intro)openRequest(intro.dataset.intro,intro.dataset.offerIndex===undefined?undefined:Number(intro.dataset.offerIndex));const action=e.target.closest('[data-action]')?.dataset.action;if(action==='request')openRequest();if(action==='add-company')openCompanyForm();if(action==='download'&&lastDraft){const d=lastDraft;const text=d.profile?`MeetAny — კომპანიის მონახაზი\n\n${d.name}\n${d.offer}\n\nტერიტორია: ${d.area}\n\nსაცდელი ვერსია. პროფილი არ გამოქვეყნებულა.`:`MeetAny — გაცნობის მოთხოვნის მონახაზი\n\nმიმღები: ${d.company}\nგამომგზავნი: ${d.name}\nელფოსტა: ${d.email}\nადგილი: ${d.city}\n\n${d.need}\n\nსაცდელი ვერსია. მოთხოვნა არ გაგზავნილა.`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=d.profile?'MeetAny-profile.txt':'MeetAny-request.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}});
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
if(document.modelContext?.registerTool&&document.querySelector('#results-grid')){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'set_catalog_filters',title:'კომპანიების ძიება',description:'Set visible MeetAny demo catalog filters and return matching fictional companies. Does not contact companies.',inputSchema:{type:'object',properties:{q:{type:'string',maxLength:200},type:{type:'string',enum:['','suppliers','services','distributors','partners']},city:{type:'string',enum:['','tbilisi','batumi','kutaisi']},language:{type:'string',enum:['','ka','en']},industry:{type:'string',enum:['',...Object.keys(filterOptions.industry)]},collaboration:{type:'string',enum:['',...Object.keys(filterOptions.collaboration)]},format:{type:'string',enum:['',...Object.keys(filterOptions.format)]},sort:{type:'string',enum:['relevance','name']}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const f=validateFilters(input);const results=setFilters(f);return{count:results.length,companies:results.map(c=>({id:c.id,name:c.name,description:c.description})),demo:true}}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

const menuButton=document.querySelector('.mobile-menu');if(menuButton){menuButton.addEventListener('click',()=>{const nav=document.querySelector('#main-nav');const open=nav.classList.toggle('is-open');menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'მენიუს დახურვა':'მენიუს გახსნა');menuButton.innerHTML=icon(open?'x':'menu');});document.querySelectorAll('#main-nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('#main-nav').classList.remove('is-open');menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','მენიუს გახსნა');menuButton.innerHTML=icon('menu');}));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('#main-nav').classList.contains('is-open')){menuButton.click();menuButton.focus();}});}

// A failed logo stays a readable company identity, never a broken image.
document.addEventListener('error',e=>{if(e.target instanceof HTMLImageElement&&e.target.classList.contains('logo-sheet'))e.target.closest('.company-logo').classList.add('logo-unavailable');},true);
document.querySelectorAll('.logo-sheet').forEach(img=>{if(img.complete&&!img.naturalWidth)img.closest('.company-logo').classList.add('logo-unavailable');});
const profile=document.querySelector('[data-profile-id]');if(profile){document.querySelector('.nav-home')?.classList.remove('active');document.querySelector('.nav-categories')?.classList.add('active');const back=safeCatalogFrom(new URLSearchParams(location.search).get('from'));document.querySelector('[data-back-to-results]').href=back;filters=readFilters(new URL(back,location.origin).search);document.querySelector('[data-copy-profile]')?.addEventListener('click',async()=>{const url=location.origin+location.pathname;try{await navigator.clipboard.writeText(url);const toast=document.querySelector('#toast');toast.textContent='კომპანიის ბმული დაკოპირებულია';toast.style.display='block';setTimeout(()=>toast.style.display='none',2500);}catch{document.querySelector('#form-content').innerHTML='<h2 id="form-title">კომპანიის ბმული</h2><p>მონიშნე და დააკოპირე ბმული.</p><div class="field"><label for="profile-link">ბმული</label><input id="profile-link" readonly value="'+esc(url)+'"></div>';document.querySelector('#form-dialog').showModal();document.querySelector('#profile-link').select();}});}

document.querySelector('#main-nav a.active')?.setAttribute('aria-current','page');

// Preserve semantic navigation when its decorative 3D asset cannot load.
function categoryImageFallback(img){if(img instanceof HTMLImageElement&&img.classList.contains('category-3d-sheet'))img.closest('.category-icon')?.classList.add('icon-unavailable');}
document.addEventListener('error',e=>categoryImageFallback(e.target),true);
document.querySelectorAll('.category-3d-sheet').forEach(img=>{if(img.complete&&!img.naturalWidth)categoryImageFallback(img);});
